begin;
create or replace function public.pause_enterprise_partner_campaign(p_campaign_id uuid) returns public.enterprise_partner_campaigns language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare c public.enterprise_partner_campaigns; b uuid; begin select n.owner_business_id into b from public.enterprise_partner_campaigns c0 join public.enterprise_partner_networks n on n.id=c0.network_id where c0.id=p_campaign_id; if b is null then raise exception 'campaign not found'; end if; if not exists(select 1 from public.business_members where business_id=b and user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Enterprise partner admin access required'; end if; if not exists(select 1 from public.businesses where id=b and lower(business_tier::text) in ('fleet','enterprise')) then raise exception 'Fleet or Enterprise plan required'; end if; update public.enterprise_partner_campaigns set status='paused',paused_at=now() where id=p_campaign_id returning * into c; return c; end $$;
create or replace function public.set_enterprise_partner_status(p_membership_id uuid,p_status text) returns public.enterprise_partner_network_members language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare m public.enterprise_partner_network_members; b uuid; begin if p_status not in ('active','paused','removed') then raise exception 'invalid partner status'; end if; select n.owner_business_id into b from public.enterprise_partner_network_members x join public.enterprise_partner_networks n on n.id=x.network_id where x.id=p_membership_id; if b is null then raise exception 'partner membership unavailable'; end if; if not exists(select 1 from public.business_members where business_id=b and user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Enterprise partner admin access required'; end if; if not exists(select 1 from public.businesses where id=b and lower(business_tier::text) in ('fleet','enterprise')) then raise exception 'Fleet or Enterprise plan required'; end if; update public.enterprise_partner_network_members set status=p_status where id=p_membership_id returning * into m; return m; end $$;
commit;
